"""Printable document adapter; escapes all external text."""
from html import escape
from erp.shared.domain import validation as cinema

def receipt(order, *, production=False):
    e=lambda v:escape(str(v));money=lambda n:f'Bs {n:.2f}'
    rows=''.join(f'<tr><td><b>{e(r["name"])}</b><br><small>{e(r["code"])} · {r["quantity"]} × {money(r["unitPrice"])}</small></td><td>{money(r["total"])}</td></tr>' for r in order['lines'])
    return f'''<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Recibo Candy {e(order['id'])}</title><style>body{{font:13px Arial;background:#e9edef;color:#17252d;margin:0}}.toolbar{{text-align:center;padding:20px}}button{{padding:12px 20px}}article{{width:72mm;padding:4mm;background:white;margin:20px auto}}header{{text-align:center;border-bottom:2px solid;padding-bottom:18px}}h1{{letter-spacing:2px;font-size:25px;margin:6px}}small{{font-size:10px}}table{{width:100%;border-collapse:collapse}}td{{padding:14px 0;border-bottom:1px dashed #aaa}}td:last-child{{text-align:right;white-space:nowrap}}.total{{display:flex;justify-content:space-between;font-size:21px;margin:22px 0}}footer{{border-top:1px dashed;padding-top:15px;text-align:center;font-size:10px;line-height:1.7}}.void{{border:2px solid;text-align:center;padding:12px;font-weight:bold}}@media print{{body{{background:white}}.toolbar{{display:none}}article{{margin:0}}@page{{size:80mm auto;margin:0}}}}</style><link rel="stylesheet" href="/reports.css"><div class="toolbar"><button onclick="window.print()">Imprimir recibo</button></div><article><header><small>MULTICINE</small><h1>UNIVERSAL</h1><b>CANDY BAR</b><p>{e(order['branch'])}</p></header>{'<p class="void">VENTA ANULADA</p>' if order.get('voided') else ''}<p>{e(order['at'][:19].replace('T',' '))}<br>Atendido por: {e(order['user'])}</p><table>{rows}</table><div class="total"><span>TOTAL</span><b>{money(order['total'])}</b></div><footer>Recibo {e(order['id'])}<br>Gracias por tu visita<br>{'' if production else 'DEMO · '}No es factura fiscal</footer></article></html>'''.encode('utf-8')
